from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','talking-toys','Talking Toys',
 ('Toys waiting in the shop','On a holiday the local market is full of people. The toys in a toy shop hope that someone will pick them. Some customers pass by, but a girl chooses Snakes and Ladders, a boy asks his Aayi for a Vande Bharat toy train, two girls take marbles and an aeroplane, and a group of children take an elephant, a spinning top and dancing dolls. This chapter also teaches describing words and plurals.'),
 [('The toy shop story',['It is a holiday and the toy shop opens at 9 a.m. It has wooden toys, soft toys, board games, bats and balls and many others.','All the toys wait to see who will buy them. Two girls pass by and only look through the window, and the toys sigh.','A girl, a little boy and their father stop. The girl chooses the board game Snakes and Ladders.','A woman and her son come in. The boy asks his Aayi, which means mother, for the Vande Bharat toy train, and she buys it.','Two girls buy marbles and a toy aeroplane. A group of children then take a toy elephant, a spinning top and dancing dolls.','The toys are happy when someone chooses them, just as we are happy when we get something we like.']),
  ('Toys of India',['Toys in India are made in many places. Chennapatna toys are wooden toys from Karnataka, and Kondapalli dancing dolls come from Andhra Pradesh.','The picture glossary shows a doll, Chennapatna toys, a Vande Bharat train, Kondapalli dancing dolls and a soft toy elephant.']),
  ('New words',['Displayed means put out where people can see it, as toys are in a shop.','Excitement is a feeling of great happiness while waiting for something.','Eagerly means with great interest and wanting something very much.']),
  ('Describing words',['The words boy, doll, frock and cap are naming words.','The word happy tells us more about the boy. Words that tell more about a naming word are describing words.','In a happy boy, a pretty doll, a blue frock and a red cap, happy, pretty, blue and red are describing words.','For example, we can say a yellow mango, clean water, cold water, a brown paper, a large tree and a white kurta.']),
  ('Plurals',['When there is more than one thing, we use a plural word. Plural means more than one.','For most words we add s: cat becomes cats, cup becomes cups, doll becomes dolls, shop becomes shops and train becomes trains.','For words ending in x, s, ch, sh or o we add es: box becomes boxes, class becomes classes, bus becomes buses, pouch becomes pouches, brush becomes brushes and mango becomes mangoes.'])],
 [('Make the plural of brush and doll.',[('Brush ends in sh.','So we add es: brushes.'),('Doll ends in l.','So we add s: dolls.'),('Brushes and dolls.','Both are plurals.')]),
  ('Find the describing word in: a pretty doll.',[('Doll names a thing.','It is a naming word.'),('Pretty tells how the doll looks.','It is a describing word.'),('So pretty is the describing word.','It tells more about the doll.')])],
 ('Tell the story of the toy shop in a few sentences.',['Toys wait for buyers','Girl chooses Snakes and Ladders','Boy asks for Vande Bharat toy','Children buy elephant, top and dolls'],['Nobody came to the toy shop','The shop closed at 9 a.m.']),
 ['The toys in the shop wait to be chosen.','Describing words tell more about naming words.','Add s to make most plurals and es to words like box and bus.','Chennapatna and Kondapalli toys are traditional Indian toys.','Aayi means mother.'],
 [M('1',1,'What game did the girl choose?','Snakes and Ladders',[('Ludo','Not in the story'),('Chess','Not in the story')],'She chose Snakes and Ladders.'),
  M('2',1,'What toy did the little boy ask for?','Vande Bharat toy train',[('Toy aeroplane','Girls bought that'),('Marbles','Girls bought that')],'He asked for the Vande Bharat train.'),
  M('3',1,'What is the plural of box?','Boxes',[('Boxs','Add es to box'),('Boxies','Not correct')],'Box ends in x, so we add es.'),
  M('4',1,'Which is a describing word?','Pretty',[('Doll','Doll names a thing'),('Shop','Shop names a place')],'Pretty tells about the doll.'),
  M('5',2,'What does Aayi mean?','Mother',[('Father','Not the meaning'),('Teacher','Not the meaning')],'Aayi is a word for mother.'),
  M('6',2,'What is the plural of doll?','Dolls',[('Dolles','Only add s'),('Dolly','Not a plural')],'Add s to doll.'),
  M('7',2,'What is the plural of bus?','Buses',[('Buss','Add es'),('Bus','That is singular')],'Bus ends in s so we add es.'),
  F('8',2,'The toys in the shop were happy when no one bought them.',False,'They sighed when people passed by.'),
  M('9',2,'Which toys come from Kondapalli?','Dancing dolls',[('Marbles','Not named'),('Spinning tops','Not named')],'Kondapalli is known for dancing dolls.'),
  S('10',2,'What is the plural of brush?',['brushes','Brushes'],'Brush ends in sh, so add es.'),
  M('11',3,'Which word tells about the naming word in "a red cap"?','red',[('cap','Cap is the naming word'),('a','A is a small word')],'Red tells more about the cap.'),
  M('12',3,'Which toy did one girl buy along with marbles bought by her friend?','A toy aeroplane',[('A toy phone','Not bought'),('A doll','Not bought')],'One girl bought marbles and the other the aeroplane.')],
 keep=['plural','describing words'])
